INSERT INTO lan_results SELECT no_plan();
INSERT INTO roles(code,name) VALUES('LAN_ACL_TEST','LAN test');
INSERT INTO permissions(code,module,action) VALUES('lan.devices.manage','lan','manage') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_code,permission_code) VALUES('LAN_ACL_TEST','lan.devices.manage');
INSERT INTO auth.users(id) SELECT actor FROM lan_fixture;
INSERT INTO user_profiles(id,auth_user_id,employee_code,full_name,pin_hash,role_code)
INSERT INTO lan_devices(id,code,name,device_type) SELECT device,'LAN-TEST-'||device::text,'Test tablet','tablet' FROM lan_fixture
INSERT INTO lan_results SELECT throws_ok($t$SELECT manage_lan_device_v1(NULL,'list')$t$,'42501','permission_denied','management requires active actor and permission');
INSERT INTO lan_results SELECT throws_ok($t$SELECT authenticate_lan_device_v1(repeat('a',64),repeat('b',64))$t$,'42501','device_unauthorized','wrong code refused');
INSERT INTO lan_results SELECT is((SELECT result->>'id' FROM paired),(SELECT device::text FROM lan_fixture),'pair resolves the registered device');
INSERT INTO lan_results SELECT ok(NOT ((SELECT result->'permissions' FROM paired) ? 'drawer.open'),'tablet has no drawer permission');
INSERT INTO lan_results SELECT throws_ok($t$SELECT authenticate_lan_device_v1(repeat('c',64),encode(extensions.digest((SELECT result->>'pairing_code' FROM lan_code),'sha256'),'hex'))$t$,'42501','device_unauthorized','used code cannot pair a different secret');
INSERT INTO lan_results SELECT lives_ok($t$SELECT authenticate_lan_device_v1(repeat('a',64),encode(extensions.digest((SELECT result->>'pairing_code' FROM lan_code),'sha256'),'hex'))$t$,'same secret retry accepted');
INSERT INTO lan_results SELECT throws_ok($t$SELECT authenticate_lan_device_v1(repeat('a',64),NULL,(SELECT other FROM lan_fixture))$t$,'42501','device_unauthorized','secret cannot claim another device');
INSERT INTO lan_results SELECT is((SELECT count(*)::integer FROM update_lan_heartbeat_v3(ARRAY[(SELECT result->>'code' FROM paired)])),1,'server heartbeat accepts paired device');
INSERT INTO lan_results SELECT is((SELECT count(*)::integer FROM update_lan_heartbeat_v3(ARRAY[(SELECT result->>'code' FROM paired)])),0,'inactive device ignored');
INSERT INTO lan_results SELECT is((SELECT is_active FROM lan_devices WHERE id=(SELECT device FROM lan_fixture)),false,'heartbeat never reactivates device');
INSERT INTO lan_results SELECT is((SELECT count(*)::integer FROM jsonb_array_elements(get_lan_registry_v1()->'devices') d WHERE d->>'id'=(SELECT device::text FROM lan_fixture)),0,'inactive device omitted from registry');
INSERT INTO lan_results SELECT is((SELECT count(*)::integer FROM jsonb_array_elements(get_lan_registry_v1()->'devices') d WHERE d->>'id'=(SELECT device::text FROM lan_fixture)),1,'active paired device in registry');
INSERT INTO lan_results SELECT throws_ok($t$SELECT authenticate_lan_device_v1(repeat('a',64),NULL,(SELECT device FROM lan_fixture))$t$,'42501','device_unauthorized','revocation refuses device');
INSERT INTO lan_results SELECT is((SELECT count(*)::integer FROM jsonb_array_elements(get_lan_registry_v1()->'devices') d WHERE d->>'id'=(SELECT device::text FROM lan_fixture)),0,'revoked device removed from registry');
INSERT INTO lan_results SELECT throws_ok($t$SELECT authenticate_lan_device_v1(repeat('d',64),encode(extensions.digest((SELECT result->>'pairing_code' FROM expired),'sha256'),'hex'))$t$,'42501','device_unauthorized','expired code refused');
