BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=public,extensions;
CREATE TEMP TABLE lan_results(line text);
GRANT INSERT ON lan_results TO authenticated,anon,kiosk_display;
CREATE TEMP TABLE lan_fixture AS SELECT gen_random_uuid() AS actor,gen_random_uuid() AS device,gen_random_uuid() AS other;
SELECT actor,actor,'LAN-'||actor::text,'LAN test','not-a-login','LAN_ACL_TEST' FROM lan_fixture;
UNION ALL SELECT other,'LAN-TEST-'||other::text,'Other tablet','tablet' FROM lan_fixture;
CREATE TEMP TABLE lan_code AS SELECT manage_lan_device_v1(actor,'issue',device) AS result FROM lan_fixture;
CREATE TEMP TABLE paired AS SELECT authenticate_lan_device_v1(repeat('a',64),encode(extensions.digest((SELECT result->>'pairing_code' FROM lan_code),'sha256'),'hex')) AS result;
UPDATE lan_devices SET is_active=false WHERE id=(SELECT device FROM lan_fixture);
UPDATE lan_devices SET is_active=true WHERE id=(SELECT device FROM lan_fixture);
SELECT manage_lan_device_v1(actor,'revoke',device) FROM lan_fixture;
CREATE TEMP TABLE expired AS SELECT manage_lan_device_v1(actor,'issue',other) AS result FROM lan_fixture;
UPDATE lan_device_credentials SET pairing_expires_at=now()-interval '1 second' WHERE device_id=(SELECT other FROM lan_fixture);
SET LOCAL ROLE authenticated;
RESET ROLE;
SELECT line FROM lan_results;
ROLLBACK;
